273→// ---------------------------------------------------------------------------
274→// Action — POST /api/recommend
275→// Body JSON: { shop, height, weight, unit, gender, bodyType, chartId }
276→// ---------------------------------------------------------------------------
277→
278→export const action = async ({ request }: ActionFunctionArgs) => {
279→  if (request.method === "OPTIONS") {
280→    return new Response(null, { status: 204, headers: CORS_HEADERS });
281→  }
282→
283→  if (request.method !== "POST") {
284→    return Response.json(
285→      { error: "Method not allowed" },
286→      { status: 405, headers: CORS_HEADERS },
287→    );
288→  }
289→
290→  let body: Partial<RecommendRequestBody>;
291→
292→  try {
293→    body = (await request.json()) as Partial<RecommendRequestBody>;
294→  } catch {
295→    return Response.json(
296→      { error: "Invalid JSON body" },
297→      { status: 400, headers: CORS_HEADERS },
298→    );
299→  }
300→
301→  const { shop, chartId, height, weight, unit, gender, bodyType } = body;
302→
303→  // Validate shop
304→  if (!shop || !SHOP_RE.test(shop)) {
305→    return Response.json(
306→      { error: "Invalid or missing shop parameter" },
307→      { status: 400, headers: CORS_HEADERS },
308→    );
309→  }
310→
311→  // Validate required fields
312→  if (!chartId) {
313→    return Response.json(
314→      { error: "chartId is required" },
315→      { status: 400, headers: CORS_HEADERS },
316→    );
317→  }
318→  if (typeof height !== "number" || height <= 0) {
319→    return Response.json(
320→      { error: "height must be a positive number" },
321→      { status: 400, headers: CORS_HEADERS },
322→    );
323→  }
324→  if (typeof weight !== "number" || weight <= 0) {
325→    return Response.json(
326→      { error: "weight must be a positive number" },
327→      { status: 400, headers: CORS_HEADERS },
328→    );
329→  }
330→  if (!unit || !["metric", "imperial"].includes(unit)) {
331→    return Response.json(
332→      { error: "unit must be 'metric' or 'imperial'" },
333→      { status: 400, headers: CORS_HEADERS },
334→    );
335→  }
336→  if (!gender || !["male", "female", "unisex"].includes(gender)) {
337→    return Response.json(
338→      { error: "gender must be 'male', 'female', or 'unisex'" },
339→      { status: 400, headers: CORS_HEADERS },
340→    );
341→  }
342→  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
343→    return Response.json(
344→      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
345→      { status: 400, headers: CORS_HEADERS },
346→    );
347→  }
348→
349→  try {
350→    // Check recommender is enabled for this shop
351→    const recommenderConfig = await db.recommenderConfig.findUnique({
352→      where: { shop },
353→    });
354→
355→    if (!recommenderConfig?.enabled) {
356→      return Response.json(
357→        { error: "AI recommender is not enabled for this shop" },
358→        { status: 403, headers: CORS_HEADERS },
359→      );
360→    }
361→
362→    // Fetch the chart scoped to this shop
363→    const chart = await db.sizeChart.findFirst({
364→      where: { id: chartId, shop, status: "active" },
365→    });
366→
367→    if (!chart) {
368→      return Response.json(
369→        { error: "Chart not found" },
370→        { status: 404, headers: CORS_HEADERS },
371→      );
372→    }
373→
374→    // Parse chart data
375→    let chartData: ChartData;
376→    try {
377→      const parsed = JSON.parse(chart.data) as unknown;
378→      if (
379→        parsed !== null &&
380→        typeof parsed === "object" &&
381→        !Array.isArray(parsed)
382→      ) {
383→        const obj = parsed as Record<string, unknown>;
384→        chartData = {
385→          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
386→          units:
387→            obj.units !== null &&
388→            typeof obj.units === "object" &&
389→            !Array.isArray(obj.units)
390→              ? (obj.units as { default: string; available: string[] })
391→              : { default: "in", available: ["in", "cm"] },
392→          rows: Array.isArray(obj.rows)
393→            ? (obj.rows as Record<string, string>[])
394→            : [],
395→        };
396→      } else {
397→        chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
398→      }
399→    } catch {
400→      chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
401→    }
402→
403→    // Convert inputs to imperial baseline
404→    const { heightIn, weightLbs } = toImperial(height, weight, unit);
405→
406→    // Map unisex → female as a neutral default (average body proportions)
407→    const calcGender: GenderCalc = gender === "male" ? "male" : "female";
408→
409→    // Estimate body measurements
410→    // bodyType is validated above; cast to satisfy strict narrowing
411→    const validBodyType = bodyType as RecommendRequestBody["bodyType"];
412→    const measurements = estimateMeasurements(
413→      heightIn,
414→      weightLbs,
415→      calcGender,
416→      validBodyType,
417→    );
418→
419→    // Run recommendation
420→    const { recommendedSize, confidence, alternatives } = recommendSize(
421→      chartData,
422→      measurements,
423→    );
424→
425→    const response: RecommendResponse = {
426→      recommendedSize,
427→      confidence,
428→      alternatives,
429→      measurements,
430→    };
431→
432→    return Response.json(response, { headers: CORS_HEADERS });
433→  } catch (error) {
434→    const message =
435→      error instanceof Error ? error.message : "Internal server error";
436→    return Response.json(
437→      { error: message },
438→      { status: 500, headers: CORS_HEADERS },
439→    );
440→  }
441→};
