 28→
 29→interface BodyTypeConfig {
 30→  id: string;
 31→  label: string;
 32→  description: string;
 33→  enabled: boolean;
 34→}
 35→
 36→interface TestResult {
 37→  size: string;
 38→  confidence: number;
 39→  alternatives: string[];
 40→  bust: number;
 41→  waist: number;
 42→  hips: number;
 43→}
 44→
 45→const DEFAULT_BODY_TYPES: BodyTypeConfig[] = [
 46→  { id: "slim", label: "Slim", description: "Narrower proportions, prefers fitted styles", enabled: true },
 47→  { id: "regular", label: "Regular", description: "Standard proportions, true-to-size fits well", enabled: true },
 48→  { id: "athletic", label: "Athletic", description: "Broader chest/shoulders, narrower waist", enabled: true },
 49→  { id: "plus", label: "Plus", description: "Fuller proportions, relaxed fit preferences", enabled: true },
 50→  { id: "petite", label: "Petite", description: "Shorter stature, petite-specific proportions", enabled: false },
 51→];
 52→
 53→const DEFAULT_FIT_PREFERENCE = "true-to-size";
 54→const DEFAULT_ALGORITHM = "basic";
 55→
