 38→
 39→export const loader = async ({ request }: LoaderFunctionArgs) => {
 40→  const { session } = await authenticate.admin(request);
 41→  const shop = session.shop;
 42→
 43→  const [
 44→    chartCount,
 45→    assignmentCount,
 46→    widgetConfig,
 47→    recommenderConfig,
 48→    subscription,
 49→  ] = await Promise.all([
 50→    db.sizeChart.count({ where: { shop } }),
 51→    db.chartAssignment.count({ where: { shop } }),
 52→    db.widgetConfig.findUnique({ where: { shop } }),
 53→    db.recommenderConfig.findUnique({ where: { shop } }),
 54→    db.subscription.findUnique({ where: { shop } }),
 55→  ]);
 56→
 57→  const plan = getPlan(subscription?.planId ?? "free");
 58→
 59→  return {
 60→    shop,
 61→    chartCount,
 62→    assignmentCount,
 63→    hasWidgetConfig: widgetConfig !== null,
 64→    widgetDisplayMode: widgetConfig?.displayMode ?? null,
 65→    hasRecommenderConfig: recommenderConfig !== null,
 66→    recommenderEnabled: recommenderConfig?.enabled ?? false,
 67→    plan,
 68→    isPriority: hasFeature(plan.id, "prioritySupport"),
 69→    isFreePlan: plan.id === "free",
 70→  };
 71→};
 72→
 73→// ---------------------------------------------------------------------------
 74→// Action
 75→// ---------------------------------------------------------------------------
 76→
 77→export const action = async ({ request }: ActionFunctionArgs) => {
 78→  const { session } = await authenticate.admin(request);
 79→  const shop = session.shop;
 80→  const formData = await request.formData();
 81→  const intent = formData.get("intent") as string;
 82→
 83→  try {
 84→    switch (intent) {
 85→      case "export-data": {
 86→        const charts = await db.sizeChart.findMany({
 87→          where: { shop },
 88→          include: { assignments: true },
 89→        });
 90→        const payload = {
 91→          exportedAt: new Date().toISOString(),
 92→          shop,
 93→          charts: charts.map((c) => ({
 94→            id: c.id,
 95→            name: c.name,
 96→            type: c.type,
 97→            category: c.category,
 98→            data: c.data,
 99→            isDefault: c.isDefault,
100→            status: c.status,
101→            createdAt: c.createdAt.toISOString(),
102→            assignments: c.assignments.map((a) => ({
103→              assignmentType: a.assignmentType,
104→              assignmentValue: a.assignmentValue,
105→            })),
106→          })),
107→        };
108→        return {
109→          ok: true,
110→          intent: "export-data",
111→          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
112→          exportData: JSON.stringify(payload, null, 2),
113→        };
114→      }
115→
116→      case "import-data": {
117→        const jsonRaw = formData.get("importJson") as string;
118→        if (!jsonRaw?.trim()) {
119→          return { error: "No JSON data provided", intent: "import-data" };
120→        }
121→        let parsed: { charts?: Array<{
122→          name: string;
123→          type?: string;
124→          category?: string;
125→          data?: string;
126→          isDefault?: boolean;
127→          status?: string;
128→          assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
129→        }> };
130→        try {
131→          parsed = JSON.parse(jsonRaw) as typeof parsed;
132→        } catch {
133→          return { error: "Invalid JSON format", intent: "import-data" };
134→        }
135→        if (!Array.isArray(parsed.charts)) {
136→          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
137→        }
138→        let imported = 0;
139→        for (const chart of parsed.charts) {
140→          if (!chart.name) continue;
141→          const existing = await db.sizeChart.findFirst({
142→            where: { shop, name: chart.name },
143→          });
144→          if (existing) continue;
145→          await db.sizeChart.create({
146→            data: {
147→              shop,
148→              name: chart.name,
149→              type: chart.type ?? "table",
150→              category: chart.category ?? "general",
151→              data: chart.data ?? "{}",
152→              isDefault: chart.isDefault ?? false,
153→              status: chart.status ?? "draft",
154→              assignments: chart.assignments
155→                ? {
156→                    create: chart.assignments.map((a) => ({
157→                      shop,
158→                      assignmentType: a.assignmentType,
159→                      assignmentValue: a.assignmentValue,
160→                    })),
161→                  }
162→                : undefined,
163→            },
164→          });
165→          imported++;
166→        }
167→        return {
168→          ok: true,
169→          intent: "import-data",
170→          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
171→        };
172→      }
173→
174→      case "reset-widget": {
175→        await db.widgetConfig.deleteMany({ where: { shop } });
176→        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
177→      }
178→
179→      case "reset-analytics": {
180→        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
181→        return {
182→          ok: true,
183→          intent: "reset-analytics",
184→          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
185→        };
186→      }
187→
188→      case "delete-all-charts": {
189→        const confirm = formData.get("confirmText") as string;
190→        if (confirm !== "DELETE") {
191→          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
192→        }
193→        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
194→        return {
195→          ok: true,
196→          intent: "delete-all-charts",
197→          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
198→        };
199→      }
200→
201→      default:
202→        return { error: "Unknown action", intent };
203→    }
204→  } catch (error) {
205→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
206→    return { error: message, intent };
207→  }
208→};
