 56→// ─── Loader ─────────────────────────────────────────────────────────────────
 57→
 58→export const loader = async ({ request }: LoaderFunctionArgs) => {
 59→  const { session } = await authenticate.admin(request);
 60→  const subscription = await db.subscription.findUnique({
 61→    where: { shop: session.shop },
 62→  });
 63→  return {
 64→    currentPlan: getPlan(subscription?.planId ?? "free"),
 65→    billingInterval: subscription?.billingInterval ?? "monthly",
 66→    plans: PLANS,
 67→  };
 68→};
 69→
 70→// ─── Action ─────────────────────────────────────────────────────────────────
 71→
 72→export const action = async ({ request }: ActionFunctionArgs) => {
 73→  const { session } = await authenticate.admin(request);
 74→  const shop = session.shop;
 75→  const formData = await request.formData();
 76→  const intent = formData.get("intent") as string;
 77→
 78→  try {
 79→    if (intent === "subscribe") {
 80→      const planId = formData.get("planId") as string;
 81→      const interval = (formData.get("interval") as string) || "monthly";
 82→      const plan = getPlan(planId);
 83→
 84→      if (plan.price === 0) {
 85→        await db.subscription.upsert({
 86→          where: { shop },
 87→          update: { planId: "free", status: "active", billingInterval: "monthly" },
 88→          create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
 89→        });
 90→        return { ok: true, message: "Switched to Free plan" };
 91→      }
 92→
 93→      // Production: call Shopify billing API here
 94→      // For now, simulate by updating local DB
 95→      await db.subscription.upsert({
 96→        where: { shop },
 97→        update: { planId, billingInterval: interval, status: "active" },
 98→        create: { shop, planId, billingInterval: interval, status: "active" },
 99→      });
100→
101→      return { ok: true, message: `Subscribed to ${plan.name} plan` };
102→    }
103→
104→    if (intent === "cancel") {
105→      await db.subscription.upsert({
106→        where: { shop },
107→        update: { planId: "free", status: "active", billingInterval: "monthly" },
108→        create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
109→      });
110→      return { ok: true, message: "Subscription cancelled. You are now on the Free plan." };
111→    }
112→
113→    return { error: "Unknown action" };
114→  } catch (error) {
115→    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
116→  }
117→};
