136→interface PlanCardProps {
137→  plan: Plan;
138→  isAnnual: boolean;
139→  currentTier: string;
140→  onSubscribe: (planId: string) => void;
141→  onRequestCancel: () => void;
142→  isLoading: boolean;
143→}
144→
145→function PlanCard({
146→  plan,
147→  isAnnual,
148→  currentTier,
149→  onSubscribe,
150→  onRequestCancel,
151→  isLoading,
152→}: PlanCardProps) {
153→  const isCurrent = currentTier === plan.id;
154→  const isMostPopular = plan.id === "growth";
155→  const tierIndex = PLAN_ORDER.indexOf(plan.id as (typeof PLAN_ORDER)[number]);
156→  const currentIndex = PLAN_ORDER.indexOf(currentTier as (typeof PLAN_ORDER)[number]);
157→  const isUpgrade = tierIndex > currentIndex;
158→  const isDowngrade = tierIndex < currentIndex;
159→
160→  const displayPrice = isAnnual
161→    ? (plan.annualPrice / 12).toFixed(2)
162→    : plan.price.toFixed(2);
163→
164→  let buttonContent = "Start free trial";
165→  let buttonVariant: "primary" | "secondary" | undefined = "primary";
166→  let buttonTone: "critical" | undefined = undefined;
167→
168→  if (isCurrent) {
169→    buttonContent = "Current plan";
170→    buttonVariant = "secondary";
171→  } else if (plan.price === 0) {
172→    buttonContent = "Downgrade to Free";
173→    buttonVariant = undefined;
174→    buttonTone = "critical";
175→  } else if (isUpgrade) {
176→    buttonContent = `Upgrade to ${plan.name}`;
177→  } else if (isDowngrade) {
178→    buttonContent = `Switch to ${plan.name}`;
179→  }
180→
181→  const handleClick = () => {
182→    if (isCurrent) return;
183→    if (plan.price === 0) {
184→      onRequestCancel();
185→    } else {
186→      onSubscribe(plan.id);
187→    }
188→  };
189→
190→  return (
191→    <Card>
192→      <BlockStack gap="400">
193→        {/* Plan name + badges */}
194→        <BlockStack gap="100">
195→          <InlineStack align="space-between" blockAlign="center">
196→            <Text as="h3" variant="headingMd" fontWeight="bold">
197→              {plan.name}
198→            </Text>
199→            <InlineStack gap="150">
200→              {isMostPopular && !isCurrent && (
201→                <Badge tone="info" icon={StarIcon}>
202→                  Most popular
203→                </Badge>
204→              )}
205→              {isCurrent && <Badge tone="success">Active</Badge>}
206→            </InlineStack>
207→          </InlineStack>
208→          <Text as="p" variant="bodySm" tone="subdued">
209→            {PLAN_DESCRIPTIONS[plan.id] ?? ""}
210→          </Text>
211→        </BlockStack>
212→
213→        <Divider />
214→
215→        {/* Price */}
216→        <BlockStack gap="100">
217→          {plan.price === 0 ? (
218→            <>
219→              <Text as="p" variant="headingXl" fontWeight="bold">
220→                Free
221→              </Text>
222→              <Text as="p" variant="bodySm" tone="subdued">
223→                forever — no credit card
224→              </Text>
225→            </>
226→          ) : (
227→            <>
228→              <InlineStack gap="100" blockAlign="baseline">
229→                <Text as="p" variant="headingXl" fontWeight="bold">
230→                  ${displayPrice}
231→                </Text>
232→                <Text as="p" variant="bodySm" tone="subdued">
233→                  / month
234→                </Text>
235→              </InlineStack>
236→              <Text as="p" variant="bodySm" tone="subdued">
237→                {isAnnual
238→                  ? `billed $${plan.annualPrice} / year`
239→                  : `or $${(plan.annualPrice / 12).toFixed(2)}/mo billed annually`}
240→              </Text>
241→            </>
242→          )}
243→        </BlockStack>
244→
245→        {/* CTA button */}
246→        <Button
247→          variant={buttonVariant}
248→          tone={buttonTone}
249→          onClick={handleClick}
250→          disabled={isCurrent}
251→          loading={isLoading && !isCurrent}
252→          fullWidth
253→        >
254→          {buttonContent}
255→        </Button>
256→
257→        <Divider />
258→
259→        {/* Features list */}
260→        <BlockStack gap="300">
261→          {plan.features.map((f) => (
262→            <PlanFeature key={f} feature={f} />
263→          ))}
264→        </BlockStack>
265→      </BlockStack>
266→    </Card>
267→  );
268→}
