107→            <span class="scrr-unit-hint" id="scrr-weight-unit-{{ block_id }}">(kg)</span>
108→          </label>
109→          <input
110→            class="scrr-input"
111→            type="number"
112→            id="scrr-weight-{{ block_id }}"
113→            name="weight"
114→            min="30"
115→            max="300"
116→            step="0.5"
117→            placeholder="65"
118→            required
119→            aria-required="true"
120→            aria-describedby="scrr-weight-err-{{ block_id }}"
