122→          <span class="scrr-field-error" id="scrr-weight-err-{{ block_id }}" role="alert" hidden></span>
123→        </div>
124→
125→        {%- comment -%} Gender {%- endcomment -%}
126→        <div class="scrr-field">
127→          <label class="scrr-label" for="scrr-gender-{{ block_id }}">
