129→          </label>
130→          <select class="scrr-select" id="scrr-gender-{{ block_id }}" name="gender" required aria-required="true">
131→            <option value="female">{{ 'products.size_chart.gender_female' | t | default: 'Female' }}</option>
132→            <option value="male">{{ 'products.size_chart.gender_male' | t | default: 'Male' }}</option>
133→            <option value="unisex">{{ 'products.size_chart.gender_unisex' | t | default: 'Unisex / Other' }}</option>
134→          </select>
135→        </div>
136→
137→        {%- comment -%} Body type {%- endcomment -%}
138→        <div class="scrr-field">
139→          <label class="scrr-label" for="scrr-bodytype-{{ block_id }}">
140→            {{ 'products.size_chart.body_type' | t | default: 'Body Type' }}
141→          </label>
142→          <select class="scrr-select" id="scrr-bodytype-{{ block_id }}" name="bodyType" required aria-required="true">
143→            <option value="slim">{{ 'products.size_chart.body_slim' | t | default: 'Slim / Petite' }}</option>
144→            <option value="average" selected>{{ 'products.size_chart.body_average' | t | default: 'Average' }}</option>
145→            <option value="athletic">{{ 'products.size_chart.body_athletic' | t | default: 'Athletic / Muscular' }}</option>
146→            <option value="plus">{{ 'products.size_chart.body_plus' | t | default: 'Plus / Curvy' }}</option>
147→          </select>
148→        </div>
149→      </div>
150→
151→      {%- comment -%} Submit {%- endcomment -%}
152→      <button class="scrr-submit" type="submit" id="scrr-submit-{{ block_id }}">
153→        <span class="scrr-submit-text">{{ 'products.size_chart.find_my_size' | t | default: 'Find My Size' }}</span>
154→        <span class="scrr-spinner" aria-hidden="true" hidden></span>
155→      </button>
156→
157→      <div class="scrr-form-error" id="scrr-form-err-{{ block_id }}" role="alert" hidden></div>
158→    </form>
159→
160→    {%- comment -%} Result {%- endcomment -%}
