502→{%- comment -%} ══ JAVASCRIPT ══════════════════════════════════════════════ {%- endcomment -%}
503→<script>
504→(function () {
505→  'use strict';
506→
507→  var BLOCK_ID   = '{{ block_id }}';
508→  var SHOP       = '{{ shop_domain }}';
509→  var PRODUCT_ID = '{{ product_id }}';
510→  var APP_BASE   = '/apps/size-chart-recommender';
511→
512→  function $(id) { return document.getElementById(id); }
513→
514→  function apiFetch(url, opts, ms) {
515→    var ctrl = new AbortController();
516→    var t = setTimeout(function () { ctrl.abort(); }, ms || 5000);
517→    return fetch(url, Object.assign({ signal: ctrl.signal }, opts || {}))
518→      .then(function (r) { clearTimeout(t); return r.ok ? r.json() : null; })
519→      .catch(function () { clearTimeout(t); return null; });
520→  }
521→
522→  function escapeHtml(str) {
523→    var d = document.createElement('div');
524→    d.appendChild(document.createTextNode(str));
525→    return d.innerHTML;
526→  }
527→
528→  // Elements
529→  var rootEl      = $('scr-rec-root-' + BLOCK_ID);
530→  var toggle      = $('scrr-toggle-' + BLOCK_ID);
531→  var body        = $('scrr-body-' + BLOCK_ID);
532→  var disabledEl  = $('scrr-disabled-' + BLOCK_ID);
533→  var form        = $('scrr-form-' + BLOCK_ID);
534→  var heightEl    = $('scrr-height-' + BLOCK_ID);
535→  var weightEl    = $('scrr-weight-' + BLOCK_ID);
536→  var heightUnit  = $('scrr-height-unit-' + BLOCK_ID);
537→  var weightUnit  = $('scrr-weight-unit-' + BLOCK_ID);
538→  var heightErr   = $('scrr-height-err-' + BLOCK_ID);
539→  var weightErr   = $('scrr-weight-err-' + BLOCK_ID);
540→  var submitBtn   = $('scrr-submit-' + BLOCK_ID);
541→  var submitText  = submitBtn ? submitBtn.querySelector('.scrr-submit-text') : null;
542→  var spinner     = submitBtn ? submitBtn.querySelector('.scrr-spinner') : null;
543→  var formErr     = $('scrr-form-err-' + BLOCK_ID);
544→  var resultEl    = $('scrr-result-' + BLOCK_ID);
545→  var resultSize  = $('scrr-result-size-' + BLOCK_ID);
546→  var resultMsg   = $('scrr-result-msg-' + BLOCK_ID);
547→  var altsWrap    = $('scrr-alts-' + BLOCK_ID);
548→  var altsChips   = $('scrr-alts-chips-' + BLOCK_ID);
549→  var redoBtn     = $('scrr-redo-' + BLOCK_ID);
550→
551→  // Apply colors from data attributes for instant paint
552→  if (rootEl) {
553→    var p = rootEl.dataset;
554→    if (p.primaryColor)  rootEl.style.setProperty('--scrr-primary',  p.primaryColor);
555→    if (p.bgColor)       rootEl.style.setProperty('--scrr-bg',       p.bgColor);
556→    if (p.textColor)     rootEl.style.setProperty('--scrr-text',     p.textColor);
557→    if (p.borderRadius)  rootEl.style.setProperty('--scrr-radius',   p.borderRadius + 'px');
558→  }
559→
560→  // Loaded chart ID (fetched lazily on first open)
561→  var chartId = null;
562→  var chartFetched = false;
563→
564→  function fetchChartId() {
565→    if (chartFetched) return;
566→    chartFetched = true;
567→    var url = APP_BASE + '/api/size-chart?shop=' + encodeURIComponent(SHOP) + '&productId=' + encodeURIComponent(PRODUCT_ID);
568→    apiFetch(url).then(function (resp) {
569→      // api.size-chart returns { id, name, category, type, data: { headers, units, rows } }
570→      if (resp && !resp.error && resp.id && resp.data) {
571→        chartId = resp.id;
572→      }
573→    });
574→  }
575→
576→  // ── Toggle expand / collapse ────────────────────────────────────────────────
577→  var isExpanded = false;
578→
579→  if (toggle && body) {
580→    toggle.addEventListener('click', function () {
581→      isExpanded = !isExpanded;
582→      toggle.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
583→      if (isExpanded) {
584→        body.removeAttribute('hidden');
585→        // Lazy-fetch chart ID when first opened
586→        fetchChartId();
587→      } else {
588→        body.setAttribute('hidden', '');
589→      }
590→    });
591→  }
592→
593→  // ── Unit system toggle ──────────────────────────────────────────────────────
594→  if (form) {
595→    form.addEventListener('change', function (e) {
596→      if (e.target.name !== 'unit') return;
597→      var isMetric = e.target.value === 'metric';
598→      if (heightUnit) heightUnit.textContent = isMetric ? '(cm)' : '(in)';
599→      if (weightUnit) weightUnit.textContent = isMetric ? '(kg)' : '(lbs)';
600→      if (heightEl) {
601→        heightEl.min   = isMetric ? '100' : '40';
602→        heightEl.max   = isMetric ? '250' : '98';
603→        heightEl.placeholder = isMetric ? '170' : '67';
604→      }
605→      if (weightEl) {
606→        weightEl.min   = isMetric ? '30'  : '66';
607→        weightEl.max   = isMetric ? '300' : '660';
608→        weightEl.placeholder = isMetric ? '65' : '143';
609→      }
610→    });
611→  }
612→
613→  // ── Helpers ─────────────────────────────────────────────────────────────────
614→  function setFieldError(el, errEl, msg) {
615→    if (el)    el.setAttribute('aria-invalid', 'true');
616→    if (errEl) { errEl.textContent = msg; errEl.removeAttribute('hidden'); }
617→  }
618→
619→  function clearFieldError(el, errEl) {
620→    if (el)    el.removeAttribute('aria-invalid');
621→    if (errEl) { errEl.textContent = ''; errEl.setAttribute('hidden', ''); }
622→  }
623→
624→  function setFormError(msg) {
625→    if (formErr) { formErr.textContent = msg; formErr.removeAttribute('hidden'); }
626→  }
627→
628→  function clearFormError() {
629→    if (formErr) { formErr.textContent = ''; formErr.setAttribute('hidden', ''); }
630→  }
631→
632→  function setSubmitting(on) {
633→    if (!submitBtn) return;
634→    submitBtn.disabled = on;
635→    if (submitText) submitText.textContent = on ? 'Calculating\u2026' : 'Find My Size';
636→    if (spinner) {
637→      if (on) spinner.removeAttribute('hidden');
638→      else    spinner.setAttribute('hidden', '');
639→    }
640→  }
641→
642→  function trackEvent(type, extra) {
643→    var body2 = Object.assign({ shop: SHOP, eventType: type, productId: PRODUCT_ID }, extra || {});
644→    apiFetch(APP_BASE + '/api/analytics-event', {
645→      method: 'POST',
646→      headers: { 'Content-Type': 'application/json' },
647→      body: JSON.stringify(body2)
648→    }, 5000);
649→  }
650→
651→  // ── Form submit ─────────────────────────────────────────────────────────────
652→  if (form) {
653→    form.addEventListener('submit', function (e) {
654→      e.preventDefault();
655→      clearFormError();
656→      clearFieldError(heightEl, heightErr);
657→      clearFieldError(weightEl, weightErr);
658→
659→      var fd      = new FormData(form);
660→      var unit    = fd.get('unit');
661→      var height  = parseFloat(fd.get('height'));
662→      var weight  = parseFloat(fd.get('weight'));
663→      var gender  = fd.get('gender');
664→      var bodyType = fd.get('bodyType');
665→
666→      var isMetric = unit === 'metric';
667→      var valid = true;
668→
669→      if (isNaN(height) || height < (isMetric ? 100 : 40) || height > (isMetric ? 250 : 98)) {
670→        setFieldError(heightEl, heightErr,
671→          'Enter a valid height (' + (isMetric ? '100-250 cm' : '40-98 inches') + ')');
672→        valid = false;
673→      }
674→      if (isNaN(weight) || weight < (isMetric ? 30 : 66) || weight > (isMetric ? 300 : 660)) {
675→        setFieldError(weightEl, weightErr,
676→          'Enter a valid weight (' + (isMetric ? '30-300 kg' : '66-660 lbs') + ')');
677→        valid = false;
678→      }
679→      if (!valid) return;
680→
681→      if (!chartId) {
682→        setFormError('Unable to load chart data. Please refresh the page and try again.');
683→        return;
684→      }
685→
686→      setSubmitting(true);
687→
688→      apiFetch(APP_BASE + '/api/recommend', {
689→        method: 'POST',
690→        headers: { 'Content-Type': 'application/json' },
691→        body: JSON.stringify({
692→          shop: SHOP,
693→          chartId: chartId,
694→          height: height,
695→          weight: weight,
696→          unit: unit,
697→          gender: gender,
698→          bodyType: bodyType
699→        })
700→      })
701→        .then(function (resp) {
702→          setSubmitting(false);
703→          if (!resp) { setFormError('Unable to get a recommendation. Please try again.'); return; }
704→          if (resp.error) {
705→            if (resp.error.includes('not enabled')) {
706→              // Show disabled notice
707→              if (disabledEl) disabledEl.removeAttribute('hidden');
708→              if (form) form.style.display = 'none';
709→            } else {
710→              setFormError(resp.error);
711→            }
712→            return;
713→          }
714→          showResult(resp);
715→          trackEvent('recommend', { sizeChartId: chartId, size: resp.recommendedSize });
716→        })
717→        .catch(function () {
718→          setSubmitting(false);
719→          setFormError('An unexpected error occurred. Please try again.');
720→        });
721→    });
722→  }
723→
724→  function showResult(resp) {
725→    if (!resultEl) return;
726→    if (form) form.style.display = 'none';
727→    resultEl.removeAttribute('hidden');
728→    if (resultSize) resultSize.textContent = resp.recommendedSize || '?';
729→    var conf = Math.round((resp.confidence || 0) * 100);
730→    if (resultMsg) {
731→      resultMsg.textContent = conf >= 80
732→        ? 'Great fit — ' + conf + '% confidence.'
733→        : conf >= 60
734→          ? 'Good fit (' + conf + '% confidence). Also check the size chart.'
735→          : 'Best estimate (' + conf + '% confidence). Check the chart for confirmation.';
736→    }
737→    var alts = resp.alternatives || [];
738→    if (altsChips && alts.length > 0) {
739→      altsChips.innerHTML = alts.map(function (a) {
740→        return '<span class="scrr-alt-chip" role="listitem">'
741→          + escapeHtml(a.size)
742→          + '<span class="scrr-alt-conf">' + Math.round((a.confidence || 0) * 100) + '%</span>'
743→          + '</span>';
744→      }).join('');
745→      if (altsWrap) altsWrap.removeAttribute('hidden');
746→    }
747→  }
748→
749→  // Redo
750→  if (redoBtn) {
751→    redoBtn.addEventListener('click', function () {
752→      if (resultEl) resultEl.setAttribute('hidden', '');
753→      if (form) form.style.display = '';
754→      clearFormError();
755→    });
756→  }
757→
758→  // Load widget config to apply server-side color overrides
759→  (function loadConfig() {
760→    var CACHE_KEY = 'scr_config_' + SHOP;
761→    var CACHE_TTL = 5 * 60 * 1000;
762→    var cached = null;
763→    try {
764→      var raw = localStorage.getItem(CACHE_KEY);
765→      if (raw) {
766→        var obj = JSON.parse(raw);
767→        if (Date.now() - obj.ts < CACHE_TTL) cached = obj.data;
768→      }
769→    } catch (e) {}
770→
771→    function applyColors(config) {
772→      if (!config || !rootEl) return;
773→      if (config.primaryColor)    rootEl.style.setProperty('--scrr-primary',  config.primaryColor);
774→      if (config.backgroundColor) rootEl.style.setProperty('--scrr-bg',       config.backgroundColor);
775→      if (config.textColor)       rootEl.style.setProperty('--scrr-text',     config.textColor);
776→      if (config.borderRadius)    rootEl.style.setProperty('--scrr-radius',   config.borderRadius + 'px');
777→      if (config.successColor)    rootEl.style.setProperty('--scrr-success',  config.successColor);
778→      if (config.errorColor)      rootEl.style.setProperty('--scrr-error',    config.errorColor);
779→    }
780→
781→    if (cached) {
782→      applyColors(cached);
783→    }
784→
785→    apiFetch(APP_BASE + '/api/widget-config?shop=' + encodeURIComponent(SHOP))
786→      .then(function (resp) {
787→        if (resp && resp.config) {
788→          try { localStorage.setItem(CACHE_KEY, JSON.stringify({ data: resp.config, ts: Date.now() })); }
789→          catch (e) {}
790→          applyColors(resp.config);
791→          // Update heading text from server config
792→          var labelEl = toggle ? toggle.querySelector('.scrr-toggle-label') : null;
793→          if (labelEl && resp.config.buttonText) labelEl.textContent = resp.config.buttonText;
794→        }
795→      });
796→  }());
797→
798→})();
799→</script>
